.param set :payment_id '$payment_id'
.param set :basket_id '$params.basket_id'
.param set :customer_id '$params.customer_id'
.param set :store_id '$store_id'
.param set :total_amount_cents $total_amount_cents
.param set :record_path '$payment_record_path'
BEGIN TRANSACTION;
INSERT INTO payment_transactions (payment_id, record_path, basket_id, is_archived_basket_reference, customer_id, store_id, payment_amount_cents, payment_currency, payment_status, payment_created_at, payment_method_fingerprint, device_fingerprint, observed_latitude, observed_longitude) VALUES (:payment_id, :record_path, :basket_id, 0, :customer_id, :store_id, :total_amount_cents, 'USD', 'completed', datetime('now'), 'trusted_override', 'trusted_override', 0.0, 0.0);
INSERT INTO payment_transaction_items (payment_id, line_number, product_sku, purchased_quantity, item_unit_price_cents) SELECT :payment_id, sbi.line_number, sbi.product_sku, sbi.requested_quantity, pv.price_cents FROM shopping_basket_items sbi JOIN product_variants pv ON sbi.product_sku = pv.product_sku WHERE sbi.basket_id = :basket_id;
UPDATE shopping_baskets SET basket_status = 'checked_out' WHERE basket_id = :basket_id;
COMMIT;
